/* edges details for region "earth", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("earth.edges",{"edges":{
"carbon-cycle:climate-energy":{"type":"connection","label":{"zh":"大气二氧化碳 → 温室效应","en":"Atmospheric CO₂ → greenhouse effect"},"reason":{"zh":"碳循环决定大气二氧化碳的浓度，浓度又改变红外逸出，是气候能量账本里的温室项。","en":"The carbon cycle sets the concentration of atmospheric CO₂, which changes infrared escape, the greenhouse term in the climate energy ledger."},"source":"../earth/climate/carbon-cycle/#step2"},
"carbon-cycle:climate-feedback":{"type":"connection","label":{"zh":"排放只有一部分留在空气里","en":"Only part of the emissions stays in the air"},"reason":{"zh":"每年排出的碳一部分被海洋和陆地吸收，其余留在大气；被吸收不等于消失——海洋会酸化，陆地吸收还受温度和水分限制。","en":"Of the carbon emitted each year, part is taken up by the ocean and land and the rest stays in the air; taken up is not gone — the ocean acidifies, and land uptake is limited by temperature and water."},"source":"../earth/climate/climate-feedback/#step1"},
"climate-energy:atmospheric-circulation":{"type":"foundation","label":{"zh":"纬度受热差 → 环流的动力","en":"Latitude heating gap → the engine of circulation"},"reason":{"zh":"单位面积受热随纬度按 cos φ 下降，由此产生的赤道—极地温差是大气环流的能量来源。","en":"Heat per area falls roughly as cos φ with latitude, and the resulting equator–pole contrast is the energy source of atmospheric circulation."},"source":"../earth/climate/atmospheric-circulation/#step0"},
"climate-energy:climate-feedback":{"type":"foundation","label":{"zh":"先对上能量账","en":"Balance the energy ledger first"},"reason":{"zh":"短波进来、红外出去，两者相等时温度稳定；温室气体让“出去”变难，地球就升温，直到顶端的进出重新相等——反馈改变的正是这本账。","en":"Shortwave light comes in and infrared goes out, and the temperature is steady when they match; greenhouse gases make going out harder, so the Earth warms until the top-of-atmosphere ledger balances again — feedbacks change that very ledger."},"source":"../earth/climate/climate-feedback/#step0"},
"conic-sections:kepler-orbits":{"type":"foundation","label":{"zh":"轨道是一条圆锥曲线","en":"An orbit is a conic section"},"reason":{"zh":"偏心率 e 把圆（e = 0）和越来越扁的椭圆（0 < e < 1）串成一族；恒星在椭圆的一个焦点上，不在中心。","en":"The eccentricity e strings together the circle (e = 0) and ever-flatter ellipses (0 < e < 1); the star sits at one focus of the ellipse, not at its centre."},"source":"../earth/astronomy/kepler-orbits/"},
"coordinate-plane:latitude-longitude":{"type":"connection","label":{"zh":"地球表面的坐标地址","en":"An address system on the globe"},"reason":{"zh":"坐标系用两个数给平面上的点定地址；经纬网用经度、纬度两个角度给球面上的点定地址，同样是先定基准线、再报两个数。","en":"A coordinate system gives a point on a plane a two-number address; latitude and longitude give a point on the sphere a two-angle address — the same idea of fixing reference lines and then reporting two numbers."},"source":"../earth/geo/latitude-longitude/#step1"},
"derivative:contour-lines":{"type":"application","label":{"zh":"疏密就是变化率","en":"Spacing is a rate of change"},"reason":{"zh":"相邻等高线海拔差固定，水平间距越短说明每走一米海拔变化越快，也就是坡度（导数的大小）越大。","en":"Neighbouring contours differ by a fixed height, so a shorter horizontal gap means altitude changes faster per metre travelled, i.e. a larger slope (the size of the derivative)."},"source":"../earth/geo/contour-lines/#step1"},
"doppler-effect:cosmic-expansion":{"type":"connection","label":{"zh":"同是红移，原因不同","en":"Both are redshifts, for different reasons"},"reason":{"zh":"多普勒红移来自光源在空间中远离；宇宙学红移是光在路上随空间一起被拉长，λ观测 = (1+z)λ₀ 由发光到接收之间尺度因子增大了多少决定——近处两者数值相近，远处不能混用。","en":"A Doppler redshift comes from a source moving away through space; a cosmological redshift is light stretched along with space on its journey, λ_obs = (1+z)λ₀ set by how much the scale factor grew between emission and reception — close by the numbers agree, far away they must not be mixed up."},"source":"../earth/astronomy/cosmology-expansion/#step2"},
"earth-rotation-day-night:moon-phases":{"type":"connection","label":{"zh":"亮的永远是一半","en":"Half is always lit"},"reason":{"zh":"太阳总照亮地球、月球朝向它的那一半；昼夜是我们随地球转进转出那半边，月相是从地球看过去，月球亮的那一半露出了多少。","en":"The Sun always lights the half of the Earth, and of the Moon, that faces it; day and night is us turning into and out of that half, while a moon phase is how much of the Moon’s lit half we can see from Earth."},"source":"../earth/astronomy/day-night-rotation/#step1"},
"earth-rotation-day-night:seasons-orbit":{"type":"connection","label":{"zh":"自转给昼夜，公转加地轴倾斜给四季","en":"Rotation gives day and night; orbit plus tilt gives seasons"},"reason":{"zh":"一天由地球绕自己的轴转一圈决定；地球同时绕太阳公转一圈是一年，再加上地轴是斜的，才有四季——两种转动别混为一谈。","en":"A day comes from the Earth turning once on its own axis; going once round the Sun takes a year, and that, together with the tilted axis, is what makes seasons — two different motions not to be confused."},"source":"../earth/astronomy/day-night-rotation/#step4"},
"feedback:climate-feedback":{"type":"foundation","label":{"zh":"回路的符号决定放大还是削弱","en":"A loop’s sign decides amplify or damp"},"reason":{"zh":"“变化 → 机制 → 下一步变化”沿回路走一圈，如果把原来的变化推得更大就是正反馈（冰雪、水汽），推回去就是负反馈（升温多散热）；控制系统里同样用回路的符号判断稳不稳。","en":"Go once round “change → mechanism → next change”: if it pushes the original change further it is positive feedback (ice, water vapour), if it pushes back it is negative (a warmer Earth radiates more); control systems judge stability by the same sign of the loop."},"source":"../earth/climate/climate-feedback/#step2"},
"gravity-orbits:kepler-orbits":{"type":"foundation","label":{"zh":"引力给出椭圆和变速","en":"Gravity produces the ellipse and the changing speed"},"reason":{"zh":"平方反比的引力让束缚轨道成为椭圆；靠近恒星时引力做正功、速度变大，远离时速度变小。","en":"An inverse-square pull makes bound orbits ellipses; falling closer, gravity speeds the planet up, and climbing away, it slows down."},"source":"../earth/astronomy/kepler-orbits/"},
"moon-phases:unit-circle":{"type":"application","label":{"zh":"位置角决定亮面比例","en":"Position angle sets the lit fraction"},"reason":{"zh":"月亮在轨道上的角度 θ 通过 cos θ 决定亮面的比例，这是单位圆上余弦的直接应用。","en":"The Moon's orbital angle θ sets the lit fraction through cos θ, a direct use of the cosine on the unit circle."},"source":"../earth/astronomy/moon-phases/#step1"},
"photosynthesis:carbon-cycle":{"type":"application","label":{"zh":"叶片尺度 → 全球尺度","en":"Leaf scale → global scale"},"reason":{"zh":"光合作用每年把约 120 GtC 从空气移入植物，与呼吸大致相抵，是碳循环里最大的陆地流量。","en":"Photosynthesis moves about 120 GtC a year from air into plants, roughly cancelled by respiration, the largest land flux in the carbon cycle."},"source":"../earth/climate/carbon-cycle/#step1"},
"seasons-orbit:atmospheric-circulation":{"type":"application","label":{"zh":"直射点移动 → 雨带与季风移动","en":"Overhead Sun moves → rain belt and monsoon move"},"reason":{"zh":"太阳直射点随季节南北移动，受热最强的纬度跟着移动，上升气流带与季风方向也随之变化。","en":"The overhead Sun moves north and south with the seasons, so the latitude of strongest heating shifts and with it the rising-air belt and monsoon direction."},"source":"../earth/climate/atmospheric-circulation/#step5"},
"seismic-waves:plate-tectonics":{"type":"connection","label":{"zh":"地震既是证据，也是探针","en":"Earthquakes are both evidence and probe"},"reason":{"zh":"地震集中发生在板块边界，是板块相对运动最直接的野外证据；同样这些地震发出的波穿过地球内部，揭示了板块下方会流动的那一层。","en":"Earthquakes cluster along plate boundaries, the most direct field evidence of relative plate motion; the waves from those same earthquakes travel through the interior and reveal the flowing layer beneath the plates."},"source":"../earth/geo/plate-tectonics/#step3"},
"sine:seasons-orbit":{"type":"application","label":{"zh":"单位面积受热 ∝ sin h","en":"Heat per area ∝ sin h"},"reason":{"zh":"太阳高度角为 h 时，一束阳光铺在地面上的面积按 1/sin h 变化，所以单位面积的受热与 sin h 成正比，这是夏热冬冷的几何原因。","en":"At Sun altitude h one beam spreads over a ground area of 1/sin h, so heat per unit area is proportional to sin h, the geometric reason summer is warm and winter cold."},"source":"../earth/astronomy/seasons-orbit/#step2"},
"slope:cosmic-expansion":{"type":"representation","label":{"zh":"H₀ 是一条直线的斜率","en":"H₀ is the slope of a line"},"reason":{"zh":"把星系的退行速度对距离作图，近处的点落在一条过原点的直线上，斜率就是哈勃常数 H₀。","en":"Plot galaxies’ recession speed against distance and the nearby points fall on a straight line through the origin whose slope is the Hubble constant H₀."},"source":"../earth/astronomy/cosmology-expansion/#step1"},
"unit-circle:latitude-longitude":{"type":"application","label":{"zh":"纬线长度 ∝ cos 纬度","en":"Parallel length ∝ cos latitude"},"reason":{"zh":"纬度 φ 处的纬线圈半径是 R·cos φ，这正是单位圆上的 cos，所以 1° 经度对应的距离随纬度按 cos φ 缩小。","en":"The parallel at latitude φ has radius R·cos φ, the same cosine as on the unit circle, so the distance for 1° of longitude shrinks like cos φ with latitude."},"source":"../earth/geo/latitude-longitude/#step1"}
}});
